#include "pch.h"
#include "ImageComparison.h"
#include "DocumentRenderer.h"
namespace sct::services {
namespace {bool Size(int aw,int ah,int bw,int bh){if(aw<1||ah<1||bw<1||bh<1||aw>32768||ah>32768||bw>32768||bh>32768)return false;return (static_cast<uint64_t>(aw)*ah+static_cast<uint64_t>(bw)*bh+static_cast<uint64_t>(std::max(aw,bw))*std::max(ah,bh))*4<=512ULL*1024*1024;}}
bool CompareImages(core::Image before,core::Image after,ImageComparison& output,CString& error,CompareOptions options){
    try{if(before.Empty()||after.Empty()||!Size(before.width,before.height,after.width,after.height)||static_cast<uint64_t>(before.width)*before.height*4!=before.pixels.size()||static_cast<uint64_t>(after.width)*after.height*4!=after.pixels.size()||options.tolerance<0||options.tolerance>255||std::abs(int64_t(options.offsetX))>32768||std::abs(int64_t(options.offsetY))>32768)throw std::runtime_error("Invalid comparison buffer/options or512MiB limit");
        const int ax=-std::min(0,options.offsetX),ay=-std::min(0,options.offsetY),bx=ax+options.offsetX,by=ay+options.offsetY,w=std::max(ax+before.width,bx+after.width),h=std::max(ay+before.height,by+after.height);const bool align=options.offsetX||options.offsetY;const uint64_t bytes=static_cast<uint64_t>(w)*h*4;if(w>32768||h>32768||before.pixels.size()+after.pixels.size()+bytes*(align?3:1)>512ULL*1024*1024)throw std::runtime_error("Registered comparison buffer limit");
        ImageComparison result;if(!result.difference.Create(w,h))throw std::runtime_error("Comparison allocation failed");result.total=static_cast<uint64_t>(w)*h;
        for(int y=0;y<h;++y)for(int x=0;x<w;++x){const bool a=x>=ax&&y>=ay&&x<ax+before.width&&y<ay+before.height,b=x>=bx&&y>=by&&x<bx+after.width&&y<by+after.height;bool changed=a!=b;if(a&&b){const auto* p=before.Row(y-ay)+(x-ax)*4;const auto* q=after.Row(y-by)+(x-bx)*4;changed=p[3]!=q[3];for(int c=0;c<3;++c)changed=changed||std::abs(int(p[c])-q[c])>options.tolerance;}auto* p=result.difference.Row(y)+x*4;if(changed){p[0]=32;p[1]=32;p[2]=240;++result.changed;}else p[0]=p[1]=p[2]=245;p[3]=255;}
        if(align){if(!result.before.Create(w,h)||!result.after.Create(w,h))throw std::runtime_error("Registration allocation failed");std::fill(result.before.pixels.begin(),result.before.pixels.end(),BYTE{0});std::fill(result.after.pixels.begin(),result.after.pixels.end(),BYTE{0});for(int y=0;y<before.height;++y)memcpy(result.before.Row(y+ay)+ax*4,before.Row(y),before.width*4);for(int y=0;y<after.height;++y)memcpy(result.after.Row(y+by)+bx*4,after.Row(y),after.width*4);}else{result.before=std::move(before);result.after=std::move(after);}output=std::move(result);return true;
    }catch(const std::exception& e){error.Format(L"Comparison: %hs",e.what());return false;}
}
bool CompareDocuments(const core::DocumentState& a,const core::DocumentState& b,ImageComparison& output,CString& error,CompareOptions options){if(!a.base||!b.base||!Size(a.base->width,a.base->height,b.base->width,b.base->height)){error=L"Comparison buffer limit (512 MiB)";return false;}core::Image before,after;return RenderDocument(a,before,error)&&RenderDocument(b,after,error)&&CompareImages(std::move(before),std::move(after),output,error,options);}
}
